def count(lo,hi,delta=800):
    n=0; ev=0
    for u,v,t in events:
        if not (lo<=t<=hi): continue
        ev+=1
        for w in set(adj[u])&set(adj[v]):
            if w in (u,v): continue
            t1=[x for x in adj[u][w] if x<t]; t2=[x for x in adj[v][w] if x<t]
            if t1 and t2 and t-max(max(t1),max(t2))<=delta:
                n+=1; break
    return ev,n
