import collections
cand=[6,10,17,37,57,72,80,87,106,111,114,116]
cs=set(cand)
adj=collections.defaultdict(lambda: collections.defaultdict(list))
for u,v,t in events:
    adj[u][v].append(t); adj[v][u].append(t)
whole=[]; delays=[]
for u,v,t in events:
    if u not in cs and v not in cs: continue
    best=None
    for w in set(adj[u])&set(adj[v]):
        if w in (u,v): continue
        t1=[x for x in adj[u][w] if x<t]; t2=[x for x in adj[v][w] if x<t]
        if t1 and t2:
            d=t-max(max(t1),max(t2))
            if best is None or d<best: best=d
    if best is not None:
        delays.append(best)
        if best<=800: whole.append((u,v,t,best))
d=sorted(delays)
print("whole-log cand prompt closures:",len(whole),whole)
print("n:",len(d),"min",d[0],"p25",d[len(d)//4],"median",d[len(d)//2])
pairs=[]
for i,a in enumerate(cand):
    for b in cand[i+1:]:
        common=set(adj[a])&set(adj[b])
        if common: pairs.append((a,b,sorted(common)))
print("cand-cand shared contacts:",pairs)
print("direct cand-cand edges:",[(a,b) for a in cand for b in cand if b in adj[a]])
